-- =========================================================
-- GDK Commerce — Data awal (kategori, brand, produk contoh)
-- Kode SKU di bawah adalah CONTOH. Jalankan api/cron/sync-products.php
-- setelah akun Digiflazz aktif untuk mengambil SKU & harga asli.
-- =========================================================
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description), icon=VALUES(icon), sort_order=VALUES(sort_order);

ON DUPLICATE KEY UPDATE name=VALUES(name), category_id=VALUES(category_id), type=VALUES(type), color=VALUES(color), mark=VALUES(mark), input_label=VALUES(input_label), input_hint=VALUES(input_hint), input_pattern=VALUES(input_pattern), input_error=VALUES(input_error), normalize=VALUES(normalize), check_name=VALUES(check_name), admin_fee=VALUES(admin_fee), df_category=VALUES(df_category), df_brand=VALUES(df_brand);

ON DUPLICATE KEY UPDATE name=VALUES(name), price_modal=VALUES(price_modal), price_sell=VALUES(price_sell), sort_order=VALUES(sort_order);
